-- Officers List: Ministry of Women and Children Affairs (MoWCA)
-- Generated from 'MoWCA_Officers_List_by_Department__2_.xlsx' (All Officers sheet)
-- MySQL dialect

DROP TABLE IF EXISTS `mowca_officers`;
CREATE TABLE `mowca_officers` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `overall_sl` INT DEFAULT NULL,
  `department` VARCHAR(255) DEFAULT NULL,
  `sl` INT DEFAULT NULL,
  `name` VARCHAR(255) DEFAULT NULL,
  `officer_id` VARCHAR(100) DEFAULT NULL,
  `designation` VARCHAR(255) DEFAULT NULL,
  `office` VARCHAR(255) DEFAULT NULL,
  `email` VARCHAR(255) DEFAULT NULL,
  `phone_office` VARCHAR(100) DEFAULT NULL,
  `mobile` VARCHAR(100) DEFAULT NULL,
  `intercom` VARCHAR(100) DEFAULT NULL,
  `room_no` VARCHAR(255) DEFAULT NULL,
  `fax` VARCHAR(100) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

